func same(a, b []int) bool {
    if len(a) != len(b) {
        return false
    }
    return true
}

for i := range a {
    if a[i] != b[i] {
        return false
    }
}

func main() {
    x := []int{1, 2}
    y := []int{1, 2}
    z := []int{2, 1}
    fmt.Println(same(x, y), same(x, z))
}

